"use strict";

/**
 * Returns a display name for a function
 * @param  {Function} func
 * @returns {string}
 */
module.exports = function functionName(func) {
    if (!func) {
        return "";
    }

    try {
        return (
            func.displayName ||
            func.name ||
            (String(func).match(/function ([^\s(]+)/) || [])[1]
        );
    } catch (e) {
        return "";
    }
};
